The **Trapezoidal rule** estimates one strip of area as $A\approx\dfrac{h}{2}(d_{f}+d_{l})$, where $h$ is the strip width.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (A) at (0,0);
\coordinate (B) at (4,0);
\coordinate (P) at (0,2.4);
\coordinate (Q) at (4,3.2);
\draw (A) -- (B) node[midway, below] {$h$};
\draw (A) -- (P) node[midway, left] {$d_{f}$};
\draw (B) -- (Q) node[midway, right] {$d_{l}$};
\draw (P) .. controls (1.4,3.3) and (2.6,2.1) .. (Q);
\coordinate (a) at ($(A)!0.3cm!(B)$);
\coordinate (b) at ($(A)!0.3cm!(P)$);
\draw (a) -- ($(a)+(b)-(A)$) -- (b);
\coordinate (c) at ($(B)!0.3cm!(A)$);
\coordinate (d) at ($(B)!0.3cm!(Q)$);
\draw (c) -- ($(c)+(d)-(B)$) -- (d);
\end{tikzpicture}
[/tikz]

